local M = {}
function M.mean(t) local s = 0 for _, v in ipairs(t) do s = s + v end return s / #t end
function M.median(t)
  local c = { table.unpack(t) }
  table.sort(c)
  local m = #c // 2
  if #c % 2 == 1 then return c[m + 1] end
  return (c[m] + c[m + 1]) / 2
end
return M
